// TH14 v1.00b st04.ecl.txt::MainSub06 entry 1192-1215.
// Dependencies: ECir00 12-45, ECir00_at 47-146, GirlD01 673-695, GirlD01_at 697-741.
// Source t0 (line 1192) maps to card frame 122: 120-frame opening buffer plus the two
// task-start frames of the control/pattern chain; the phase timer starts at card frame 1.
// Source waits after 1192 are kept verbatim; the card window only adds the 120-frame buffer.
const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// ===== MainSub06 1192-1215: GirlD01 groups and ECir00 pairs =====
async sub pattern() {
    wait(OPENING_BUFFER);
    // 1192-1193: enmCreate GirlD01(0,-32), wait 140
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, girl_d01);
    wait(140);
    // 1194-1202: B=3; loop enmCreate + enmCreateM ECir00 at (0,0), 20/20 frames
    for i in 0..3 {
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir00(1));
        wait(20);
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir00(-1));
        wait(20);
    }
    // 1203-1205: wait 180; GirlD01 pair at (+-96,-32)
    wait(180);
    _ = spawn_enemy(96fx, -32fx, 800, 0, 0, 0, girl_d01);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, girl_d01);
    // 1206-1215: wait 60; A=0,C=7; 7x enmCreateM ECir00 at (A,0), A+=10, 20 frames
    wait(60);
    var ax: fx = 0fx;
    for j in 0..7 {
        _ = spawn_enemy(ax, 0fx, 150, 0, 0, 0, ecir00(-1));
        wait(20);
        ax = ax + 10fx;
    }
}

// ===== GirlD01 673-695 =====
async sub girl_d01() {
    set_invuln(65535);
    // setHurtbox(32,32) -> circular branch first value x0.5; setHitbox(24,24) likewise.
    set_hurtbox(16fx);
    set_hitbox(12fx);
    // moveVel(pi/2, 1.4): down 1.4 px/frame.
    move_vel(0, 90deg, 1.4fx, EASE_LINEAR);
    // moveSpeedTime(60, mode1, 0.0): quadratic accel toward 0.
    move_speed(60, 0fx, EASE_QUAD_IN);
    spawn girl_d01_at();
    wait(120);
    // moveSpeedTime(80, mode1, 1.0): quadratic accel back to 1.0.
    move_speed(80, 1fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// 697-741: wait 60; two paired bullets per wave (radial offsets +-C, 20deg shrinking by 0.98).
sub girl_shot(b: fx, r: fx) {
    // Sampling order per bullet: etOffsetRad RANDF2, etAngle RANDF2, etSpeed RANDF.
    var u1: fx = (rand(65536) - 32768) as fx / 32768;
    var oa: angle = ((b * u1) as int) as angle;
    var u2: fx = (rand(65536) - 32768) as fx / 32768;
    var ang: angle = 90deg + (((1092fx * u2) as int) as angle);
    var u3: fx = ((rand(65536) - 32768) as fx / 65536) + 0.5fx;
    var spd: fx = 1fx + 1.5fx * u3;
    sh_offset_rad(0, oa, r);
    sh_angle(0, ang, 0deg);
    sh_speed(0, spd, 0fx);
    // etEx type2 ANIM: spawn position -= 4 * initial velocity.
    sh_dist(0, -4fx * spd);
    sh_fire(0);
}

async sub girl_d01_at() {
    wait(60);
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 6);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    var rank: int = global(GVAR_RANK);
    var outer: int = rank + 1;      // diffI(A, 1, 2, 3, 4)
    var wave_wait: int = 4 - rank;  // wait rank: E4 / N3 / H2 / L1
    for it in 0..outer {
        var b: fx = 3641fx;  // %B = 0.349066 rad = 20deg, held in BAM
        var c: fx = 8fx;     // %C, radius of the radial spawn offset
        for w in 0..15 {     // $D = 15 waves
            girl_shot(b, c);
            girl_shot(b, 0fx - c);
            c = c + 10fx;
            b = b * 0.98fx;
            wait(wave_wait);
        }
    }
}

// ===== ECir00 12-45 =====
async sub ecir00(sign: int) {
    set_invuln(65535);
    // setHurtbox(24,24) -> 12; setHitbox(16,16) -> 8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    var s: fx = sign as fx;
    var bx: fx = $self_x;
    // movePosRel(-192*sign, 0): the REL layer starts offset from the spawn point.
    move_to(0, bx - 192fx * s, 0fx, EASE_LINEAR);
    // flagSet(15) entry mask: 0x2 is the no-body gate; 0x4/0x8 skip offscreen recycling,
    // which has no target counterpart (target enemies are not recycled by x).
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // moveBezierRel(120, 256A,-30, 160A,128, 0,0): REL Hermite, tangents in normalized time.
    hermite_start(0, bx - 192fx * s, bx + 160fx * s, 256fx * s, 0fx, 120);
    hermite_start(1, 0fx, 128fx, 0fx - 30fx, 0fx, 120);
    for i in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // flagClear(15) before the second path and before firing.
    set_enemy_flag(ENEMY_NO_BODY, 0);
    // moveBezierRel(120, 0,0, -220A,192, -200A,-228).
    hermite_start(0, bx + 160fx * s, bx - 220fx * s, 0fx, 0fx - 200fx * s, 120);
    hermite_start(1, 128fx, 192fx, 0fx, 0fx - 228fx, 120);
    for j in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 38: @ECir00_at() async; 39-43: wait(1000) loop.
    spawn ecir00_at();
    loop { wait(1000); }
}

// ===== ECir00_at 47-146 =====
// etAim mode8 bullet: per-bullet angle random then speed random; ANIM -4*velocity retreat.
sub ecir_random(aim: angle, amp: fx) {
    var u1: fx = (rand(65536) - 32768) as fx / 32768;
    var ang: angle = aim + (((3277fx * u1) as int) as angle);
    var u2: fx = ((rand(65536) - 32768) as fx / 65536) + 0.5fx;
    var spd: fx = 1fx + amp * u2;
    sh_angle(0, ang, 0deg);
    sh_speed(0, spd, 0fx);
    sh_dist(0, -4fx * spd);
    sh_fire(0);
}

// etAim mode1 fan slot: absolute angle, fixed speed.
sub ecir_fixed(aim: angle, off: angle, spd: fx) {
    sh_angle(0, aim + off, 0deg);
    sh_speed(0, spd, 0fx);
    sh_dist(0, -4fx * spd);
    sh_fire(0);
}

async sub ecir00_at() {
    var rank: int = global(GVAR_RANK);
    // 83: diffI(A, 1,1,1,8); 133-141: wait E600/N50/H10/L8.
    var shots: int = 1;
    if rank >= 3 { shots = 8; }
    var wave_wait: int = 8;
    if rank == 0 { wave_wait = 600; } else { if rank == 1 { wave_wait = 50; } else { if rank == 2 { wave_wait = 10; } } }
    // 72-81: laser length E128/N128/H144/L160; etSpeed E2.7/N3.5/H4.5/L5.0.
    var lmax: fx = 128fx;
    var grow: fx = 2.7fx;
    if rank == 1 { grow = 3.5fx; }
    if rank == 2 { lmax = 144fx; grow = 4.5fx; }
    if rank == 3 { lmax = 160fx; grow = 5fx; }
    var rod: fx = lmax * 0.8fx;  // Line ruling segment is 0.8L long
    // 89-131: mode8 block count E1/N3/H5/L5 with speed amplitude E2.0/N2.5/H2.5/L3.0.
    var amp: fx = 2fx;
    var n: int = 1;
    if rank == 1 { amp = 2.5fx; n = 3; }
    if rank == 2 { amp = 2.5fx; n = 5; }
    if rank == 3 { amp = 3fx; n = 5; }
    wait(10);
    sh_reset(0);
    sh_sprite(0, TH14_BALL, 8);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, 1, 1);
    for k in 0..shots {
        // laserNew(0, 0, L, 0, 14) + laserOn(0): straight Line grown along the current aim.
        // width 14 -> Line half-height w/4 = 3.5 -> target width 7.
        var lz: int = laser(3, $self_x, $self_y, 0deg, 0fx, 7fx, 0, 300, 10);
        lz_aim(lz, 0deg);
        lz_speed(lz, grow, rod);
        // Line flags 0x2 unset: 0.1L..0.9L of the current length is the dangerous segment,
        // modelled as a rod grown then flown out; near-end shift is not reproduced.
        if rank >= 1 {
            var aim: angle = aim_player();
            for i in 0..n {
                ecir_random(aim, amp);
            }
            // 115-131: mode1 two-way, aim +-1.5deg, speed 2.
            ecir_fixed(aim, 1.5deg, 2fx);
            ecir_fixed(aim, -1.5deg, 2fx);
        }
        wait(wave_wait);
    }
}

// ===== training shell =====
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

